5222→+	}
5223→+
5224→+	model := a.model
5225→+	if cfg.Model != "" {
5226→+		model = cfg.Model
5227→+	}
5228→+
5229→+	args := []string{"run"}
5230→+	if model != "" {
5231→+		args = append(args, "--model", model)
5232→+	}
5233→+	args = append(args, prompt)
5234→+
