5236→+	if envTimeout := os.Getenv("E2E_TIMEOUT"); envTimeout != "" {
5237→+		if parsed, err := time.ParseDuration(envTimeout); err == nil {
5238→+			timeout = parsed
5239→+		}
5240→+	}
5241→+
5242→+	ctx, cancel := context.WithTimeout(ctx, timeout)
