5323→+
5324→+// TmuxSession implements Session using tmux for PTY-based interactive agents.
5325→+type TmuxSession struct {
5326→+	name         string
5327→+	stableAtSend string // stable content snapshot when Send was last called
5328→+}
5329→+
5330→+// NewTmuxSession creates a new tmux session running the given command in dir.
5331→+// unsetEnv lists environment variable names to strip from the session.
5332→+func NewTmuxSession(name string, dir string, unsetEnv []string, command string, args ...string) (*TmuxSession, error) {
5333→+	s := &TmuxSession{name: name}
5334→+
5335→+	tmuxArgs := []string{"new-session", "-d", "-s", name, "-c", dir}
5336→+	// Build the shell command, prefixed with env -u for each var to strip.
5337→+	shellCmd := ""
5338→+	var shellCmdSb25 strings.Builder
5339→+	for _, v := range unsetEnv {
5340→+		shellCmdSb25.WriteString("env -u " + v + " ")
5341→+	}
5342→+	shellCmd += shellCmdSb25.String()
5343→+	shellCmd += command
5344→+	var shellCmdSb29 strings.Builder
5345→+	for _, a := range args {
5346→+		shellCmdSb29.WriteString(" " + a)
5347→+	}
5348→+	shellCmd += shellCmdSb29.String()
5349→+	tmuxArgs = append(tmuxArgs, shellCmd)
5350→+
5351→+	cmd := exec.Command("tmux", tmuxArgs...)
5352→+	if out, err := cmd.CombinedOutput(); err != nil {
5353→+		return nil, fmt.Errorf("tmux new-session: %w\n%s", err, out)
5354→+	}
5355→+	// Keep the pane around after the command exits so we can capture error output.
5356→+	setCmd := exec.Command("tmux", "set-option", "-t", name, "remain-on-exit", "on")
5357→+	_ = setCmd.Run()
5358→+	return s, nil
5359→+}
5360→+
5361→+func (s *TmuxSession) Send(input string) error {
5362→+	s.stableAtSend = stableContent(s.Capture())
5363→+	// Send text and Enter separately — Claude's TUI can swallow Enter
5364→+	// if it arrives before the input handler finishes processing the text.
5365→+	if err := s.SendKeys(input); err != nil {
5366→+		return err
5367→+	}
5368→+	time.Sleep(200 * time.Millisecond)
5369→+	return s.SendKeys("Enter")
5370→+}
5371→+
5372→+// SendKeys sends raw tmux key names without appending Enter.
5373→+func (s *TmuxSession) SendKeys(keys ...string) error {
5374→+	args := append([]string{"send-keys", "-t", s.name}, keys...)
5375→+	cmd := exec.Command("tmux", args...)
5376→+	out, err := cmd.CombinedOutput()
5377→+	if err != nil {
5378→+		return fmt.Errorf("tmux send-keys: %w\n%s", err, out)
5379→+	}
5380→+	return nil
5381→+}
5382→+
5383→+const settleTime = 2 * time.Second
5384→+
5385→+// stableContent returns the content with the last few lines stripped,
5386→+// so that TUI status bar updates don't prevent the settle timer.
5387→+func stableContent(content string) string {
5388→+	lines := strings.Split(content, "\n")
5389→+	if len(lines) > 3 {
5390→+		lines = lines[:len(lines)-3]
5391→+	}
5392→+	return strings.Join(lines, "\n")
5393→+}
5394→+
5395→+func (s *TmuxSession) WaitFor(pattern string, timeout time.Duration) (string, error) {
5396→+	re, err := regexp.Compile(pattern)
5397→+	if err != nil {
5398→+		return "", fmt.Errorf("invalid pattern: %w", err)
5399→+	}
5400→+
5401→+	deadline := time.Now().Add(timeout)
5402→+	var matchedAt time.Time
5403→+	var lastStable string
5404→+	contentChanged := s.stableAtSend == "" // skip change requirement for initial waits
5405→+
5406→+	for time.Now().Before(deadline) {
5407→+		content := s.Capture()
5408→+		stable := stableContent(content)
5409→+
5410→+		if !re.MatchString(content) {
5411→+			// Pattern lost — reset
5412→+			matchedAt = time.Time{}
5413→+			lastStable = ""
5414→+			time.Sleep(500 * time.Millisecond)
5415→+			continue
5416→+		}
5417→+
5418→+		// Detect content change since Send was called
5419→+		if !contentChanged && stable != s.stableAtSend {
5420→+			contentChanged = true
5421→+		}
5422→+
5423→+		if stable != lastStable {
5424→+			// Pattern matches but content is still changing — reset settle timer
5425→+			matchedAt = time.Now()
5426→+			lastStable = stable
5427→+			time.Sleep(500 * time.Millisecond)
5428→+			continue
5429→+		}
5430→+
5431→+		// Pattern matches and content hasn't changed since matchedAt.
5432→+		// Only settle if content changed at least once after Send
5433→+		// (prevents false settle on echoed input before agent starts).
5434→+		if contentChanged && time.Since(matchedAt) >= settleTime {
5435→+			return content, nil
5436→+		}
5437→+
5438→+		time.Sleep(500 * time.Millisecond)
5439→+	}
5440→+	content := s.Capture()
5441→+	return content, fmt.Errorf("timed out waiting for %q after %s\n--- pane content ---\n%s\n--- end pane content ---", pattern, timeout, content)
5442→+}
5443→+
5444→+func (s *TmuxSession) Capture() string {
5445→+	cmd := exec.Command("tmux", "capture-pane", "-t", s.name, "-p")
5446→+	out, _ := cmd.Output()
5447→+	return strings.TrimRight(string(out), "\n")
5448→+}
5449→+
5450→+func (s *TmuxSession) Close() error {
5451→+	cmd := exec.Command("tmux", "kill-session", "-t", s.name)
5452→+	out, err := cmd.CombinedOutput()
5453→+	if err != nil {
5454→+		return fmt.Errorf("tmux kill-session: %w\n%s", err, out)
5455→+	}
5456→+	return nil
5457→+}
