5569→+func parseEvents(r io.Reader) []*parentTest {
5570→+	scanner := bufio.NewScanner(r)
5571→+	scanner.Buffer(make([]byte, 0, 1024*1024), 1024*1024)
5572→+
5573→+	type testInfo struct {
5574→+		action  string
5575→+		elapsed float64
5576→+		output  []string
5577→+	}
5578→+
5579→+	tests := make(map[string]*testInfo)
5580→+
5581→+	for scanner.Scan() {
5582→+		var ev TestEvent
5583→+		if err := json.Unmarshal(scanner.Bytes(), &ev); err != nil {
5584→+			continue
5585→+		}
5586→+		if ev.Test == "" {
5587→+			continue
5588→+		}
5589→+
5590→+		info, ok := tests[ev.Test]
5591→+		if !ok {
5592→+			info = &testInfo{}
5593→+			tests[ev.Test] = info
5594→+		}
5595→+
5596→+		switch ev.Action {
5597→+		case "pass", "fail", "skip":
5598→+			info.action = ev.Action
5599→+			info.elapsed = ev.Elapsed
5600→+		case "output":
5601→+			info.output = append(info.output, ev.Output)
5602→+		}
5603→+	}
5604→+
5605→+	// Group by parent
5606→+	parentMap := make(map[string]*parentTest)
5607→+	for name, info := range tests {
5608→+		parentName, childName := splitTestName(name)
5609→+		if childName == "" {
5610→+			// This is a parent test (or standalone)
5611→+			p, ok := parentMap[parentName]
5612→+			if !ok {
5613→+				p = &parentTest{name: parentName}
5614→+				parentMap[parentName] = p
5615→+			}
5616→+			p.action = info.action
5617→+			p.elapsed = info.elapsed
5618→+			continue
5619→+		}
5620→+
5621→+		p, ok := parentMap[parentName]
5622→+		if !ok {
5623→+			p = &parentTest{name: parentName}
5624→+			parentMap[parentName] = p
5625→+		}
5626→+		p.children = append(p.children, &subtest{
5627→+			name:    childName,
5628→+			action:  info.action,
5629→+			elapsed: info.elapsed,
5630→+			output:  info.output,
5631→+		})
5632→+	}
5633→+
5634→+	// Sort parents alphabetically, children alphabetically
5635→+	var result []*parentTest
5636→+	for _, p := range parentMap {
5637→+		sort.Slice(p.children, func(i, j int) bool {
5638→+			return p.children[i].name < p.children[j].name
5639→+		})
5640→+		result = append(result, p)
5641→+	}
5642→+	sort.Slice(result, func(i, j int) bool {
5643→+		return result[i].name < result[j].name
5644→+	})
5645→+
5646→+	return result
5647→+}
