5657→+func renderReport(parents []*parentTest, color bool) string {
5658→+	var b strings.Builder
5659→+
5660→+	// Count totals
5661→+	var total, passed, failed, skipped int
5662→+	for _, p := range parents {
5663→+		total++
5664→+		switch p.action {
5665→+		case "pass":
5666→+			passed++
5667→+		case "fail":
5668→+			failed++
5669→+		case "skip":
5670→+			skipped++
5671→+		}
5672→+	}
5673→+
5674→+	// Header
5675→+	b.WriteString("E2E Test Report\n")
5676→+	b.WriteString("═══════════════\n\n")
5677→+	fmt.Fprintf(&b, "Total: %d  Passed: %d  Failed: %d  Skipped: %d\n\n", total, passed, failed, skipped)
5678→+
5679→+	for _, p := range parents {
5680→+		icon := statusIcon(p.action, color)
5681→+		if p.elapsed > 0 {
5682→+			fmt.Fprintf(&b, "%s %s (%.1fs)\n", icon, p.name, p.elapsed)
5683→+		} else {
5684→+			fmt.Fprintf(&b, "%s %s\n", icon, p.name)
5685→+		}
5686→+
5687→+		for _, c := range p.children {
5688→+			cIcon := statusIcon(c.action, color)
5689→+			switch c.action {
5690→+			case "skip":
5691→+				reason := extractSkipReason(c.output)
5692→+				fmt.Fprintf(&b, "  %s %-20s SKIP", cIcon, c.name)
5693→+				if reason != "" {
5694→+					fmt.Fprintf(&b, ": %s", reason)
5695→+				}
5696→+				b.WriteString("\n")
5697→+			case "fail":
5698→+				fmt.Fprintf(&b, "  %s %-20s %.1fs\n", cIcon, c.name, c.elapsed)
5699→+				for _, line := range filterFailureOutput(c.output) {
5700→+					fmt.Fprintf(&b, "      %s\n", line)
5701→+				}
5702→+			default:
5703→+				fmt.Fprintf(&b, "  %s %-20s %.1fs\n", cIcon, c.name, c.elapsed)
5704→+			}
5705→+		}
5706→+
5707→+		b.WriteString("\n")
5708→+	}
5709→+
5710→+	return b.String()
5711→+}
