5713→+const (
5714→+	colorGreen  = "\033[32m"
5715→+	colorRed    = "\033[31m"
5716→+	colorYellow = "\033[33m"
5717→+	colorReset  = "\033[0m"
5718→+)
5719→+
5720→+func statusIcon(action string, color bool) string {
5721→+	switch action {
5722→+	case "pass":
5723→+		if color {
5724→+			return colorGreen + "✓" + colorReset
5725→+		}
5726→+		return "✓"
5727→+	case "fail":
5728→+		if color {
5729→+			return colorRed + "✗" + colorReset
5730→+		}
5731→+		return "✗"
5732→+	case "skip":
5733→+		if color {
5734→+			return colorYellow + "−" + colorReset
5735→+		}
5736→+		return "−"
5737→+	default:
5738→+		return "?"
5739→+	}
5740→+}
