5742→+func extractSkipReason(output []string) string {
5743→+	for _, line := range output {
5744→+		trimmed := strings.TrimSpace(line)
5745→+		if strings.HasPrefix(trimmed, "--- SKIP") || strings.HasPrefix(trimmed, "=== RUN") {
5746→+			continue
5747→+		}
5748→+		if trimmed == "" {
5749→+			continue
5750→+		}
5751→+		return trimmed
5752→+	}
5753→+	return ""
5754→+}
5755→+
5756→+func filterFailureOutput(output []string) []string {
5757→+	var lines []string
5758→+	for _, line := range output {
5759→+		trimmed := strings.TrimSpace(line)
5760→+		if trimmed == "" {
5761→+			continue
5762→+		}
5763→+		if strings.HasPrefix(trimmed, "=== RUN") ||
5764→+			strings.HasPrefix(trimmed, "=== PAUSE") ||
5765→+			strings.HasPrefix(trimmed, "=== CONT") ||
5766→+			strings.HasPrefix(trimmed, "--- FAIL") ||
5767→+			strings.HasPrefix(trimmed, "--- PASS") {
5768→+			continue
5769→+		}
5770→+		lines = append(lines, trimmed)
5771→+	}
5772→+	return lines
5773→+}
